package com.example

import com.example.ExamQuestionHelper.QSpec

object MusicLiveExamThaatTheoryBank1 {
    private const val T = "ථාට දහය හා රාග න්‍යාය මූලධර්ම"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("උත්තර භාරතීය සංගීතයේ සියලු රාග ක්‍රමවත්ව වර්ගීකරණය කිරීමට පණ්ඩිත් විෂ්ණු නාරායන භාත්ඛණ්ඩේ යොදාගත් ප්‍රධාන ථාට සංඛ්‍යාව කොපමණද?", "10 කි", "7 කි", "12 කි", "72 කි", "භාත්ඛණ්ඩේ මැතිඳුන් උත්තර භාරතීය රාග ප්‍රධාන ථාට 10ක් යටතේ වර්ග කළේය."),
        q("සප්තකයේ සියලුම ස්වර ශුද්ධ ස්වර ලෙස පමණක් යෙදෙන මූලික ථාටය කුමක්ද?", "බිලාවල් ථාටය", "කල්‍යාණ් ථාටය", "ඛමාජ් ථාටය", "භෛරව් ථාටය", "බිලාවල් ථාටයේ විකෘති ස්වර කිසිවක් නොයෙදේ."),
        q("තීව්‍ර මධ්‍යමය (ම්) පමණක් විකෘති වී අනෙක් සියලු ස්වර ශුද්ධ ලෙස යෙදෙන ථාටය කුමක්ද?", "කල්‍යාණ් ථාටය", "කාෆි ථාටය", "භෛරවී ථාටය", "තෝඩි ථාටය", "යමන් හා භූපාලි වැනි රාග උපදින කල්‍යාණ් ථාටයේ එකම විකෘති ස්වරය තීව්‍ර මධ්‍යමයයි."),
        q("කෝමල නිෂාදය (නි̱) පමණක් විකෘති ස්වරය ලෙස යෙදෙන ථාටය හඳුන්වන්නේ කුමන නමින්ද?", "ඛමාජ් ථාටය", "මාරවා ථාටය", "පූර්වි ථාටය", "අසාවරී ථාටය", "ඛමාජ් සහ දේශ් රාග බිහි කරන ඛමාජ් ථාටයේ නි පමණක් කෝමල වේ."),
        q("කෝමල ගාන්ධාරය (ග̱) සහ කෝමල නිෂාදය (නි̱) යන ස්වර දෙක විකෘති වන ථාටය කුමක්ද?", "කාෆි ථාටය", "භෛරව් ථාටය", "ඛමාජ් ථාටය", "බිලාවල් ථාටය", "කාෆි සහ බාගේශ්‍රී රාග අයත් කාෆි ථාටයේ ග හා නි කෝමල වේ."),
        q("කෝමල රිෂභය (රි̱) සහ කෝමල ධෛවතය (ධ̱) විකෘති ස්වර ලෙස යෙදෙන ථාටය කුමක්ද?", "භෛරව් ථාටය", "අසාවරී ථාටය", "මාරවා ථාටය", "කල්‍යාණ් ථාටය", "ප්‍රභාත රාග සමූහයට මුල් වන භෛරව් ථාටයේ රි හා ධ කෝමල වේ."),
        q("කෝමල ගාන්ධාරය, කෝමල ධෛවතය සහ කෝමල නිෂාදය යන ස්වර තුන විකෘති වන ථාටය කුමක්ද?", "අසාවරී ථාටය", "භෛරවී ථාටය", "තෝඩි ථාටය", "පූර්වි ථාටය", "ග, ධ, නි කෝමල වීම අසාවරී ථාටයේ විශේෂ ලක්ෂණයයි."),
        q("කෝමල රි, ග, ධ, නි යන ස්වර හතරම විකෘති වන ථාටය හඳුන්වන්නේ කුමන නමින්ද?", "භෛරවී ථාටය", "භෛරව් ථාටය", "තෝඩි ථාටය", "කාෆි ථාටය", "කෝමල ස්වර හතරම යෙදෙන එකම ථාටය භෛරවී ථාටයයි."),
        q("කෝමල රිෂභය සහ තීව්‍ර මධ්‍යමය (ම්) යන ස්වර දෙක විකෘති වන ථාටය කුමක්ද?", "මාරවා ථාටය", "පූර්වි ථාටය", "ඛමාජ් ථාටය", "කාෆි ථාටය", "මාරවා ථාටයේ රි කෝමල වන අතර මධ්‍යමය තීව්‍ර වේ."),
        q("කෝමල රි, කෝමල ධ සහ තීව්‍ර මධ්‍යමය යෙදෙන සන්ධ්‍යා ප්‍රහර ථාටය කුමක්ද?", "පූර්වි ථාටය", "තෝඩි ථාටය", "අසාවරී ථාටය", "මාරවා ථාටය", "පූර්වි ථාටයේ රි̱, ධ̱ සහ තීව්‍ර ම් යන විකෘති ස්වර තුන පවතී."),
        q("කෝමල රි, ග, ධ සහ තීව්‍ර ම් යන විකෘති ස්වර හතර යෙදෙන ථාටය කුමක්ද?", "තෝඩි ථාටය", "භෛරවී ථාටය", "පූර්වි ථාටය", "මාරවා ථාටය", "මියාන් කී තෝඩි වැනි උදෑසන රාග බිහි කරන තෝඩි ථාටයේ රි̱, ග̱, ධ̱, ම් යෙදේ."),
        q("'ථාට' යන සංගීත පාරිභාෂික පදයේ ප්‍රධාන ලක්ෂණයක් වන්නේ කුමක්ද?", "සැමවිටම ස්වර හතම අනුපිළිවෙළින් පැවතීම", "ස්වර පහක් පමණක් අඩංගු වීම", "අවරෝහණ ගමනක් පමණක් තිබීම", "වාදී සහ සංවාදී ස්වර තිබීම", "ථාටයක් සැමවිටම සම්පූර්ණ ස්වර 7ක ආරෝහණ සැකිල්ලක් පමණක් වේ."),
        q("ථාටයක් සහ රාගයක් අතර ඇති ප්‍රධාන වෙනස්කම කුමක්ද?", "ථාටය රාග බිහි කරන මව් සැකිල්ල වන අතර රාගය රස උපදවන සංගීත නිර්මාණයයි", "ථාටය ගායනා කරන අතර රාගය ලියා තැබීමට පමණක් භාවිත කෙරේ", "රාගවලට වඩා ථාට සංඛ්‍යාව වැඩිය", "ථාටයක තාල තිබෙන අතර රාගයක ස්වර නොමැත", "ථාටයක් සෘජුව රස වින්දනයට නොගැයෙන අතර රාගය රස ජනනය කරයි."),
        q("රාගයක 'ජාතිය' තීරණය කරනු ලබන්නේ කුමන සාධකය මත පදනම්වද?", "ආරෝහණයේ සහ අවරෝහණයේ යෙදෙන ස්වර සංඛ්‍යාව මත", "රාගය ගායනා කරන දවසේ වේලාව මත", "රාගය අයත් වන ථාටයේ නාමය මත", "රාගයේ භාවිත කරන තාලයේ මාත්‍රා ගණන මත", "ස්වර 5, 6 හෝ 7 යෙදෙන ආකාරය අනුව ජාතිය නම් කෙරේ."),
        q("ආරෝහණයේ ස්වර 5 ක් සහ අවරෝහණයේ ස්වර 5 ක් යෙදෙන රාගයක ජාතිය කුමක්ද?", "ඕඩව - ඕඩව", "ෂාඩව - ෂාඩව", "සම්පූර්ණ - සම්පූර්ණ", "ඕඩව - ෂාඩව", "ස්වර 5ක් යෙදීම 'ඕඩව' නම් වන බැවින් 5-5 ජාතිය ඕඩව-ඕඩව වේ."),
        q("ආරෝහණයේ ස්වර 6 ක් සහ අවරෝහණයේ ස්වර 6 ක් යෙදෙන රාග ජාතිය කුමක්ද?", "ෂාඩව - ෂාඩව", "ඕඩව - ඕඩව", "ඕඩව - සම්පූර්ණ", "සම්පූර්ණ - ෂාඩව", "ස්වර 6ක් ඇති රාග භේදය ෂාඩව ලෙස හඳුන්වනු ලැබේ."),
        q("ආරෝහණයේ ස්වර 7 ම සහ අවරෝහණයේ ස්වර 7 ම යෙදෙන රාගයක ජාතිය හඳුන්වන්නේ කෙසේද?", "සම්පූර්ණ - සම්පූර්ණ", "ඕඩව - සම්පූර්ණ", "ෂාඩව - සම්පූර්ණ", "ඕඩව - ඕඩව", "කිසිදු වර්ජිත ස්වරයක් නැති රාග සම්පූර්ණ-සම්පූර්ණ ජාතියට අයත් වේ."),
        q("ආරෝහණයේ ස්වර 5 ක් සහ අවරෝහණයේ ස්වර 7 ම යෙදෙන රාගයක ජාතිය කුමක්ද?", "ඕඩව - සම්පූර්ණ", "සම්පූර්ණ - ඕඩව", "ෂාඩව - සම්පූර්ණ", "ඕඩව - ෂාඩව", "මුලින් ආරෝහණ ජාතියද දෙවනුව අවරෝහණ ජාතියද සඳහන් කෙරේ."),
        q("ආරෝහණයේ ස්වර 6 ක් සහ අවරෝහණයේ ස්වර 7 ක් යෙදෙන රාගයක ජාතිය කුමක්ද?", "ෂාඩව - සම්පූර්ණ", "ඕඩව - සම්පූර්ණ", "සම්පූර්ණ - ෂාඩව", "ෂාඩව - ඕඩව", "ඛමාජ් රාගයේ මෙන් ආරෝහණයේ 6 හා අවරෝහණයේ 7 යෙදීම ෂාඩව-සම්පූර්ණ වේ."),
        q("ප්‍රධාන ජාති 3 ඇසුරෙන් (ඕඩව, ෂාඩව, සම්පූර්ණ) සෑදිය හැකි මුළු උප රාග ජාති සංඛ්‍යාව කොපමණද?", "9 කි", "3 කි", "6 කි", "12 කි", "ආරෝහණ විධි 3 × අවරෝහණ විධි 3 = මුළු රාග ජාති 9ක් බිහි වේ."),
        q("යම් රාගයක් හඳුනාගැනීම සඳහා යොදාගන්නා ඉතා කෙටි හා ලාක්ෂණික ස්වර සමූහය කුමක්ද?", "පකඩ (Pakad)", "ථාටය", "තාලිය", "ඛාලිය", "පකඩ යනු රාගයේ සැබෑ මුහුණුවර කෙටියෙන් දක්වන ස්වර රටාවයි."),
        q("යම් රාගයක් තමන්ගේම නමින් හඳුන්වන ථාටයෙන් බිහි වන්නේ නම් එම රාගය හඳුන්වන්නේ කුමන නමින්ද?", "ආශ්‍රය රාගය", "ජන්‍ය රාගය", "සන්ධිප්‍රකාශ රාගය", "ප්‍රමෙලප්‍රවේශක රාගය", "උදාහරණ ලෙස කාෆි, භෛරව්, ඛමාජ් යන රාග තම නම ඇති ථාටයේම ආශ්‍රය රාග වේ."),
        q("ථාටයක් තුළ කිසි විටෙක පැවතිය නොහැකි තත්ත්වය කුමක්ද?", "එකම ස්වරයේ ශුද්ධ හා විකෘති රූප දෙකම එකට යෙදීම", "සප්තකයේ ස්වර හත ක්‍රමයෙන් පැවතීම", "ෂඩ්ජය සහ පංචමය යෙදීම", "රාග කිහිපයකට මව් සැකිල්ලක් වීම", "ථාටයක සෑම ස්වර නාමයකින්ම එක් ස්වරූපයක් පමණක් තිබිය යුතුය."),
        q("රාගයක් සෑදීම සඳහා අවම වශයෙන් තිබිය යුතු ස්වර සංඛ්‍යාව කොපමණද?", "ස්වර 5 ක්", "ස්වර 3 ක්", "ස්වර 7 ක්", "ස්වර 4 ක්", "ශාස්ත්‍රීය නියමය අනුව රාගයකට අවම වශයෙන් ස්වර පහක්වත් තිබිය යුතුය."),
        q("ශුද්ධ රි, ග, ධ, නි සහ ශුද්ධ ම යෙදෙන රාග අයත් වන්නේ දවසේ කුමන කාල කාණ්ඩයටද?", "පූර්වාංග හා සාමාන්‍ය දහවල්/රාත්‍රී කාලවලට", "සන්ධිප්‍රකාශ කාලයට පමණක්", "මධ්‍යම රාත්‍රියේ තෙවන ප්‍රහරයට පමණක්", "හිරු බැස යන මොහොතට පමණක්", "කෝමල රි-ධ රහිත ශුද්ධ රි-ග-ධ-නි රාග දහවල් හා රාත්‍රී මධ්‍ය ප්‍රහරවල ගැයේ."),
        q("කෝමල රිෂභය සහ කෝමල ධෛවතය සහිත රාග ගැයීමට නියමිත ප්‍රධාන වේලාව කුමක්ද?", "සන්ධිප්‍රකාශ කාලය (හිරු උදාව සහ හිරු බැසීම)", "මධ්‍යහ්න 12 සිට 3 දක්වා", "මධ්‍යම රාත්‍රී 12 සිට 3 දක්වා", "පෙරවරු 10 සිට දහවල් 12 දක්වා", "භෛරව්, පූර්වි හා මාරවා ථාට රාග සන්ධිප්‍රකාශ වේලාවන්හි ගායනා කෙරේ."),
        q("සන්ධිප්‍රකාශ රාගයක විශේෂ ලක්ෂණයක් වන කෝමල ස්වර යුගලය මොනවාද?", "කෝමල රි සහ කෝමල ධ", "කෝමල ග සහ කෝමල නි", "කෝමල රි සහ කෝමල නි", "කෝමල ග සහ කෝමල ධ", "දිවා රාත්‍රී සන්ධි වන උදේ-හවස සන්ධිප්‍රකාශ රාග රි̱ සහ ධ̱ මත පදනම් වේ."),
        q("දක්ෂිණ භාරතීය (කර්ණාටක) සංගීතයේ රාග වර්ගීකරණය සඳහා භාවිත කරන මව් රාග ක්‍රමය කුමක්ද?", "72 මේලකර්තා ක්‍රමය", "10 ථාට ක්‍රමය", "6 රාග - 36 රාගිනී ක්‍රමය", "9 රස වර්ගීකරණය", "වෙන්කටමඛී විද්වතාණන් ගණිතමය වශයෙන් සකස් කළ මේලකර්තා 72 ක්‍රමය කර්ණාටකයේ භාවිත වේ."),
        q("මධ්‍යකාලීන ඉන්දීය සංගීතයේදී භාත්ඛණ්ඩේ ථාට 10 ක්‍රමයට පෙර පැවති රාග වර්ගීකරණ ක්‍රමය කුමක්ද?", "රාග - රාගිනී ක්‍රමය", "ස්ටාෆ් නොටේෂන් ක්‍රමය", "කර්ණාටක ජාති ක්‍රමය", "ජන ගී ක්‍රමය", "ප්‍රධාන පුරුෂ රාග 6කට රාගිනියන් 5 හෝ 6 බැගින් වූ රාග-රාගිනී ක්‍රමය පැරණි ක්‍රමයකි."),
        q("උදෑසන සන්ධිප්‍රකාශ රාග සහ සවස සන්ධිප්‍රකාශ රාග එකිනෙකින් වෙන් කර හඳුනා ගන්නා ප්‍රධාන ස්වරය කුමක්ද?", "මධ්‍යමය (ශුද්ධ ම හෝ තීව්‍ර ම්)", "ෂඩ්ජය (ස)", "පංචමය (ප)", "කෝමල නිෂාදය (නි̱)", "උදෑසන රාගවල ශුද්ධ ම ද, සවස සන්ධිප්‍රකාශ රාගවල තීව්‍ර ම් ද ප්‍රමුඛ වේ."),
        q("රාගයක් ගායනයේදී තාලයකින් තොරව නිදහසේ රාගයේ ස්වරූපය හා භාවය විදහා දැක්වීම කුමක්ද?", "අලාප (Alap)", "ද්‍රුත තානය", "දුගුන් ලයකාරිය", "තිහායි කොටස", "රාග විස්තාරයේ පළමු අදියර වන අලාපය තාල රහිතව සෙමින් ඉදිරිපත් කෙරේ."),
        q("රාග ගායනයේදී ඛයාල් හෝ බණ්ඩිස් ගීතයක පළමු කොටස හඳුන්වන්නේ කුමන නමින්ද?", "ස්ථායි (Sthayi)", "අන්තරා (Antara)", "සංචාරී", "ආභෝග", "බණ්ඩිස් ගීතයේ මන්ද්‍ර හා මධ්‍ය සප්තකයේ පවතින මුල් කොටස ස්ථායි නම් වේ."),
        q("බණ්ඩිස් ගීතයක තාර සප්තකය දක්වා විහිදෙන දෙවන කොටස හඳුන්වන්නේ කෙසේද?", "අන්තරා (Antara)", "ස්ථායි (Sthayi)", "අලාප", "පකඩ", "මධ්‍ය සප්තකයේ ඉහළ ස්වර හා තාර සප්තකයේ ගමන් කරන කොටස අන්තරාවයි."),
        q("රාගයේ ලක්ෂණ, ථාටය, වාදී-සංවාදී සහ වේලාව පිළිබඳ විස්තර ගීත පදවලින්ම ගායනා කරන රචනය කුමක්ද?", "ලක්ෂණ ගීතය", "සර්ගම් ගීතය", "තාරානා ගීතය", "ධමාර් ගීතය", "රාගයේ ව්‍යාකරණ හා නීති සිසුන්ට මතක තබා ගැනීමට ලක්ෂණ ගීත නිර්මාණය විය."),
        q("කිසිදු සාහිත්‍ය වචනයක් නොමැතිව තාලයකට අනුව ස, රි, ග, ම අක්ෂර ගායනා කරන රචනා විශේෂය කුමක්ද?", "ස්වර මාලිකා (සර්ගම් ගීත)", "ලක්ෂණ ගීත", "නූර්ති ගීත", "භජන් ගීත", "තාලයකට හා රාගයකට අනුව ස්වර නාමවලින් පමණක් ගයන ගීත ස්වර මාලිකා වේ."),
        q("බණ්ඩිස් ගීතයක් තාලයට ගායනා කිරීමේදී රාගයේ ස්වර ඉතා වේගයෙන් රටා මවමින් ගැයීම කුමක්ද?", "තාන් (Taan)", "විලම්බිත අලාප", "ඛාලි පෙළගැස්ම", "සම පිරවීම", "වේගවත් ස්වර සංයෝජන මඟින් රාගයේ ජවය පෙන්වන අංගය තාන් නම් වේ."),
        q("ගීතයේ වචන කොටස් යොදා ගනිමින් රාග ස්වර වේගවත් තාන් රටාවකින් ගැයීම හඳුන්වන්නේ කෙසේද?", "බෝල්තාන් (Bol-taan)", "ආකාර තාන්", "සරල සර්ගම්", "අවරෝහණ පකඩ", "සාහිත්‍ය පද හෙවත් බෝල් භාවිතයෙන් තාන් ගැයීම බෝල්තාන් වේ."),
        q("දිනක පැය 24 ක කාලය රාග ගායන වේලා අනුව කොටස් කීයකට බෙදා තිබේද?", "ප්‍රහර 8 කට", "ප්‍රහර 4 කට", "ප්‍රහර 12 කට", "ප්‍රහර 6 කට", "එක් ප්‍රහරයක් පැය 3 බැගින් දිවා රාත්‍රී දෙක පැය 24 තුළ ප්‍රහර 8කට බෙදේ."),
        q("රාග ගායන වේලා ක්‍රමය අනුව 'ප්‍රහරයක්' සඳහා අයත් වන කාල සීමාව කොපමණද?", "පැය 3 ක්", "පැය 6 ක්", "පැය 2 ක්", "පැය 4 ක්", "දිවා ප්‍රහර 4ක් සහ රාත්‍රී ප්‍රහර 4ක් ලෙස එක් ප්‍රහරයකට පැය 3ක් වේ."),
        q("දිනයේ 'පළමු ප්‍රහරය' හෙවත් උදෑසන ප්‍රථම කාල පරිච්ඡේදය ආරම්භ වන්නේ කීයටද?", "පෙරවරු 6.00 ට පමණ", "මධ්‍යහ්න 12.00 ට පමණ", "සවස 6.00 ට පමණ", "මධ්‍යම රාත්‍රී 12.00 ට පමණ", "හිරු උදාව වන පෙ.ව. 6 සිට 9 දක්වා දිවා ප්‍රථම ප්‍රහරයයි."),
        q("රාත්‍රී පළමු ප්‍රහරය ලෙස සංගීතයේදී සලකනු ලබන වේලාව කුමක්ද?", "සවස 6.00 සිට රාත්‍රී 9.00 දක්වා", "රාත්‍රී 9.00 සිට මධ්‍යම රාත්‍රී 12.00 දක්වා", "පෙරවරු 6.00 සිට 9.00 දක්වා", "අලුයම 3.00 සිට 6.00 දක්වා", "සූර්යාස්තයෙන් පසු සවස 6–9 කාලය යමන් හා භූපාලි වැනි රාගවලට වෙන්වේ."),
        q("උත්තර භාරතීය ශාස්ත්‍රීය සංගීතයේදී 'තීව්‍ර මධ්‍යමය' සමඟ කිසිදු කෝමල ස්වරයක් නොයෙදෙන ථාටය කුමක්ද?", "කල්‍යාණ් ථාටය", "පූර්වි ථාටය", "මාරවා ථාටය", "තෝඩි ථාටය", "කල්‍යාණ් ථාටයේ අනෙක් සියලු ස්වර ශුද්ධ වන අතර 'ම' පමණක් තීව්‍ර වේ."),
        q("සියලුම ථාට 10 අතුරින් 'කෝමල ස්වර 4ක්ම' අඩංගු වන ථාටය හඳුන්වන්නේ කුමන නමින්ද?", "භෛරවී ථාටය", "අසාවරී ථාටය", "තෝඩි ථාටය", "භෛරව් ථාටය", "රි, ග, ධ, නි යන කෝමල ස්වර සතරම භෛරවී ථාටයේ ඇත."),
        q("සෑම ථාටයකම කිසිදු වෙනසකින් තොරව නියතව අනිවාර්යයෙන්ම තිබෙන ස්වර දෙක මොනවාද?", "ස සහ ප", "ස සහ ම", "ග සහ නි", "රි සහ ධ", "අචල ස්වර වන ෂඩ්ජය හා පංචමය සෑම ථාටයකම ස්ථිරව පවතී."),
        q("පහත දැක්වෙන ථාට යුගල අතුරින් ත්‍රීව්‍ර මධ්‍යමය (ම්) යෙදෙන ථාට මොනවාද?", "මාරවා, පූර්වි, තෝඩි සහ කල්‍යාණ්", "බිලාවල්, ඛමාජ්, කාෆි සහ අසාවරී", "භෛරව්, භෛරවී, කාෆි සහ ඛමාජ්", "බිලාවල්, භෛරව්, අසාවරී සහ තෝඩි", "තීව්‍ර මධ්‍යමය යෙදෙන්නේ කල්‍යාණ්, මාරවා, පූර්වි සහ තෝඩි යන ථාට 4 තුළ පමණි."),
        q("කෝමල ගාන්ධාරය (ග̱) පමණක් නොව කෝමල රිෂභය, කෝමල ධෛවතය හා තීව්‍ර මධ්‍යමයද ඇතුළත් ථාටය කුමක්ද?", "තෝඩි ථාටය", "භෛරවී ථාටය", "පූර්වි ථාටය", "කාෆි ථාටය", "තෝඩි ථාටයේ ස්වර මාලාව ස රි̱ ග̱ ම් ප ධ̱ නි සඃ වේ."),
        q("භෛරව් ථාටය සහ භෛරවී ථාටය අතර පවතින ස්වර වෙනස කුමක්ද?", "භෛරව්හි ග සහ නි ශුද්ධ වන අතර භෛරවීහි ග සහ නි කෝමල වේ", "භෛරව්හි ම තීව්‍ර වන අතර භෛරවීහි ප වර්ජිත වේ", "භෛරව්හි සියලු ස්වර කෝමල වන අතර භෛරවීහි ශුද්ධ වේ", "වෙනසක් නැතිව ස්වර හතම එක සමාන වේ", "භෛරව්හි රි-ධ පමණක් කෝමල වන අතර භෛරවීහි රි-ග-ධ-නි කෝමල වේ."),
        q("බිලාවල් ථාටයේ ස්වරයකින් නිෂාදය (නි) කෝමල කළ විට ලැබෙන නව ථාටය කුමක්ද?", "ඛමාජ් ථාටය", "කාෆි ථාටය", "කල්‍යාණ් ථාටය", "අසාවරී ථාටය", "බිලාවල්හි නි කෝමල වූ විට එය ඛමාජ් ථාටය බවට පත්වේ."),
        q("ඛමාජ් ථාටයේ ගාන්ධාරය (ග) කෝමල කළ විට ලැබෙන ථාටය කුමක්ද?", "කාෆි ථාටය", "අසාවරී ථාටය", "භෛරවී ථාටය", "භෛරව් ථාටය", "කෝමල නි ට අමතරව ග ද කෝමල වූ විට කාෆි ථාටය ලැබේ."),
        q("කාෆි ථාටයේ ධෛවතය (ධ) කෝමල කළ විට නිර්මාණය වන ථාටය කුමක්ද?", "අසාවරී ථාටය", "භෛරවී ථාටය", "ඛමාජ් ථාටය", "මාරවා ථාටය", "ග, ධ, නි කෝමල වීමෙන් අසාවරී ථාටය සෑදේ."),
        q("අසාවරී ථාටයේ රිෂභය (රි) කෝමල කළ විට ලැබෙන ථාටය හඳුන්වන්නේ කුමන නමින්ද?", "භෛරවී ථාටය", "තෝඩි ථාටය", "පූර්වි ථාටය", "භෛරව් ථාටය", "ග, ධ, නි සමඟ රි ද කෝමල වූ විට භෛරවී ථාටය බවට පත් වේ."),
        q("රාගයක් ශාස්ත්‍රීයව නිවැරදි වීම සඳහා එහි අනිවාර්යයෙන්ම අඩංගු විය යුතු ස්වරය කුමක්ද?", "ෂඩ්ජය (ස)", "තීව්‍ර මධ්‍යමය (ම්)", "කෝමල රිෂභය (රි̱)", "නිෂාදය (නි)", "ෂඩ්ජය කිසිදු රාගයකින් වර්ජිත කළ නොහැකි මූලිකම ස්වරයයි."),
        q("සෑම රාගයකම 'මධ්‍යම' (ම) සහ 'පංචම' (ප) යන ස්වර දෙක සම්බන්ධයෙන් පවතින රාග නියමය කුමක්ද?", "ම සහ ප යන ස්වර දෙකම එකවර වර්ජිත කළ නොහැකිය", "සෑම රාගයකම ම සහ ප දෙකම තීව්‍ර විය යුතුය", "ම සහ ප ස්වර රාගවල මන්ද්‍ර සප්තකයේ පමණක් ගැයේ", "එක් රාගයකට ම හෝ ප ස්වරවලින් එකක් හෝ තිබිය නොහැකිය", "රාගයක සමතුලිතතාව රැකීමට ම හෝ ප ස්වරවලින් අවම එකක්වත් පැවතිය යුතුය."),
        q("කිසියම් රාගයක එක් ස්වරයක ශුද්ධ හා විකෘති ප්‍රභේද දෙකම යෙදිය හැකිද?", "ඔව්, ක්‍රමානුකූල රාග නියම අනුව යෙදිය හැකිය", "නැත, කිසිදු රාගයක එසේ යෙදිය නොහැකිය", "ස සහ ප සඳහා පමණක් එසේ යෙදිය හැකිය", "වර්ජිත ස්වර සඳහා පමණක් යෙදේ", "උදාහරණ ලෙස ඛමාජ් රාගයේ ශුද්ධ නි සහ කෝමල නි දෙකම යෙදේ."),
        q("වේලාව අනුව රාග බෙදීමේදී 'පූර්වාංග ප්‍රධාන' රාගවල වාදී ස්වරය පිහිටන්නේ කුමන ස්වර අතරද?", "ස, රි, ග, ම අතර", "ප, ධ, නි, සඃ අතර", "ම, ප, ධ, නි අතර", "රි, ග, ධ, නි අතර", "සප්තකයේ පළමු අර්ධය වන ස-රි-ග-ම අතර වාදී ස්වරය පිහිටීම පූර්වාංග ප්‍රධාන වේ."),
        q("සන්ධිප්‍රකාශ රාගයක් ගැයීමට වඩාත් උචිත පරිසර වේලාව කුමක්ද?", "උදෑසන 4–7 හෝ සවස 4–7 අතර කාලය", "මධ්‍යහ්න 12 සිට 3 අතර කාලය", "මධ්‍යම රාත්‍රී 12 සිට 3 අතර කාලය", "පෙරවරු 9 සිට 12 අතර කාලය", "දිවා රාත්‍රී දෙක හමුවන සන්ධි කාලයන් මෙම රාග සඳහා වෙන් කර ඇත."),
        q("භාත්ඛණ්ඩේ ථාට 10 පද්ධතියෙහි 'පරමේල් ප්‍රවේශක රාගයක්' යනු කුමක්ද?", "එක් ථාටයකින් තවත් ථාට කාලයකට ප්‍රවේශ වීමේ ලක්ෂණ පෙන්වන රාගය", "ස්වර පහක් පමණක් ඇති මන්ද්‍ර රාගය", "ගායනය අවසන් කරන ස්වර ඛණ්ඩය", "ජන ගීවලින් උපුටා ගත් රාගය", "එක් කාල කලාපයක සිට මීළඟ කාල කලාපයට මාරුවීමේදී දෙපසම ලක්ෂණ ඇති රාග මෙසේ හැඳින්වේ."),
        q("උත්තර භාරතීය ශාස්ත්‍රීය ගායනයේදී වර්තමානයේ ඉතාම ජනප්‍රිය සම්භාව්‍ය ගායන ශෛලිය කුමක්ද?", "ඛයාල් (Khayal)", "සෝපාන සංගීතය", "නාඩගම් සින්දු", "ගැමි පැල් කවි", "විලම්බිත හා ද්‍රුත ලය දෙකින්ම ගැයෙන ඛයාල් සම්ප්‍රදාය නූතන ශාස්ත්‍රීය ගායනයේ ප්‍රධාන වේ."),
        q("මෝගල් යුගයට පෙර භාරතයේ පැවති අතිශය ගාම්භීර හා දැඩි නීතිරීති සහිත සම්භාව්‍ය ගායන ක්‍රමය කුමක්ද?", "ධෲපද් (Dhrupad)", "ගසල් (Ghazal)", "ඨුම්රි (Thumri)", "භජන් (Bhajan)", "තාන්සේන් ආදී සංගීතඥයින් ප්‍රගුණ කළ චෞතාලයෙන් ගයන ගාම්භීර ක්‍රමය ධෲපද්ය."),
        q("ධෲපද් ගායනය සඳහා සාම්ප්‍රදායිකව වාදනය කරනු ලබන දෙපැත්ත සම ඇති බෙර විශේෂය කුමක්ද?", "පඛාවජ් (මෘදංග)", "තබ්ලා", "රබාන", "ඩෝලකය", "ධෲපද් සහ ධමාර් ගායනයේදී තබ්ලාව වෙනුවට ගාම්භීර නාදැති පඛාවජ් බෙරය යොදයි."),
        q("උත්තර භාරතීය ථාට 10 අතරින් සියලුම ශුද්ධ ස්වර හතම අඩංගු වන ශුද්ධ ථාටය කුමක්ද?", "බිලාවල් ථාටය", "කල්‍යාණ් ථාටය", "භෛරව් ථාටය", "ඛමාජ් ථාටය", "ස-රි-ග-ම-ප-ධ-නි යන ශුද්ධ ස්වර සියල්ලම ඇතුළත් මූලික ථාටය බිලාවල් වේ."),
        q("කල්‍යාණ් ථාටයට අයත් ප්‍රධාන ස්වර ලක්ෂණය වන්නේ මධ්‍යමය කෙසේ පිහිටීමද?", "තීව්‍ර මධ්‍යමය (ම්) ලෙස පිහිටීම", "කෝමල මධ්‍යමය ලෙස පිහිටීම", "මධ්‍යමය සම්පූර්ණයෙන් වර්ජිත වීම", "මන්ද්‍ර සප්තකයේ පමණක් තිබීම", "කල්‍යාණ් ථාටයේ අනෙක් ස්වර ශුද්ධ වන අතර මධ්‍යමය පමණක් තීව්‍ර වේ."),
        q("භෛරව් ථාටයේ යෙදෙන කෝමල විකෘති ස්වර දෙක නිවැරදිව දැක්වෙන පිළිතුර කුමක්ද?", "කෝමල රි (රි̱) සහ කෝමල ධ (ධ̱)", "කෝමල ග (ග̱) සහ කෝමල නි (නි̱)", "තීව්‍ර ම (ම්) සහ කෝමල රි (රි̱)", "කෝමල රි, ග, ධ, නි හතරම", "භෛරව් ථාටයේ ග සහ නි ශුද්ධ වන අතර රි සහ ධ කෝමල වේ."),
        q("මාරවා ථාටයේ ස්වර මාලාවෙහි අඩංගු වන විකෘති ස්වර දෙක මොනවාද?", "කෝමල රිෂභය (රි̱) සහ තීව්‍ර මධ්‍යමය (ම්)", "කෝමල ග සහ කෝමල නි", "කෝමල ධ සහ කෝමල නි", "ශුද්ධ ස්වර පමණි", "මාරවා ථාටයේ ස රි̱ ග ම් ප ධ නි සඃ යන ස්වර අඩංගු වේ."),
        q("පූර්වි ථාටයේ ස්වර පෙළෙහි දක්නට ලැබෙන විකෘති ස්වර තුන කුමක්ද?", "කෝමල රි, තීව්‍ර ම සහ කෝමල ධ", "කෝමල ග, කෝමල ධ සහ කෝමල නි", "කෝමල රි, කෝමල ග සහ තීව්‍ර ම", "ශුද්ධ රි, ග, ම", "මාරවා ථාටයේ ධෛවතය කෝමල කළ විට පූර්වි ථාටය සෑදේ (රි̱, ම්, ධ̱)."),
        q("තෝඩි ථාටයේ යෙදෙන විකෘති ස්වර හතර නිවැරදිව දැක්වෙන්නේ කුමන වරණයේද?", "කෝමල රි, කෝමල ග, තීව්‍ර ම සහ කෝමල ධ", "කෝමල රි, ග, ධ සහ කෝමල නි", "ශුද්ධ රි, ග, ධ සහ තීව්‍ර ම", "කෝමල ග, නි සහ තීව්‍ර ම", "තෝඩි ථාටයේ නිෂාදය ශුද්ධ වන අතර රි, ග, ධ කෝමලද ම තීව්‍රද වේ."),
        q("පූර්වි ථාටයේ සහ භෛරව් ථාටයේ ඇති සමාන කෝමල ස්වර දෙක මොනවාද?", "කෝමල රි සහ කෝමල ධ", "කෝමල ග සහ කෝමල නි", "තීව්‍ර ම සහ කෝමල නි", "කෝමල රි සහ කෝමල ග", "මධ්‍යමය භෛරව්හි ශුද්ධ වන අතර පූර්විහි තීව්‍ර වුවද රි-ධ දෙකෙහිම කෝමල වේ."),
        q("මාරවා ථාටය සහ කල්‍යාණ් ථාටය අතර පවතින එකම ස්වර වෙනස කුමක්ද?", "මාරවාහි රි කෝමල වන අතර කල්‍යාණ්හි රි ශුද්ධ වේ", "මාරවාහි ම ශුද්ධ වන අතර කල්‍යාණ්හි තීව්‍ර වේ", "මාරවාහි ප වර්ජිත වේ", "කල්‍යාණ්හි නි කෝමල වේ", "කල්‍යාණ් ථාටයේ රිෂභය කෝමල කළ විට එය මාරවා ථාටය බවට පත්වේ."),
        q("යම් රාගයක 'ආරෝහණයේ ස්වර 5ක්ද අවරෝහණයේ ස්වර 6ක්ද' යෙදේ නම් එම රාගයේ ජාතිය කුමක්ද?", "ඕඩව - ෂාඩව", "ෂාඩව - සම්පූර්ණ", "ඕඩව - ඕඩව", "සම්පූර්ණ - සම්පූර්ණ", "ආරෝහණයට ස්වර 5 (ඕඩව) හා අවරෝහණයට ස්වර 6 (ෂාඩව) නිසා එය ඕඩව-ෂාඩව ජාතිය වේ."),
        q("ආරෝහණයේ ස්වර 6ක් හා අවරෝහණයේ ස්වර 7ක් යෙදෙන රාගයක ජාතිය හඳුන්වන්නේ කෙසේද?", "ෂාඩව - සම්පූර්ණ", "ඕඩව - සම්පූර්ණ", "සම්පූර්ණ - ෂාඩව", "ඕඩව - ෂාඩව", "ආරෝහණ 6 (ෂාඩව) හා අවරෝහණ 7 (සම්පූර්ණ) යන ජාති ප්‍රභේදයට මෙය අයත්ය."),
        q("රාගයක් සම්පූර්ණ - සම්පූර්ණ ජාතියට අයත් වන්නේ එහි ආරෝහණ අවරෝහණ දෙකේම ස්වර කීයක් යෙදෙන විටද?", "ස්වර 7 බැගින්", "ස්වර 5 බැගින්", "ස්වර 6 බැගින්", "ස්වර 4 බැගින්", "සප්ත ස්වර හතම ආරෝහණයේ හා අවරෝහණයේ යෙදීම සම්පූර්ණ-සම්පූර්ණ ජාතියයි."),
        q("ප්‍රධාන ජාති තුන වන ඕඩව, ෂාඩව සහ සම්පූර්ණ එක්වී නිර්මාණය වන මුළු උප ජාති සංඛ්‍යාව කීයද?", "9 කි (3 × 3 = 9)", "3 කි", "6 කි", "12 කි", "ඕඩව-ඕඩව, ඕඩව-ෂාඩව, ඕඩව-සම්පූර්ණ ආදී ලෙස ප්‍රධාන උප ජාති 9ක් පවතී."),
        q("සංගීත ශාස්ත්‍රයේදී 'ථාට' හා 'රාග' අතර ඇති ප්‍රධාන වෙනස්කම්වලින් එකක් වන්නේ කුමක්ද?", "ථාටයක් ගායනා නොකරන අතර රාගයක් රස විඳීම සඳහා ගායනා කෙරේ", "ථාටයක ස්වර 5ක් ඇති අතර රාගයක ස්වර 7ක්ම තිබිය යුතුය", "රාගයක ආරෝහණ අවරෝහණ නැත", "ථාටයකට තාලයක් හා වාදී ස්වරයක් ඇත", "ථාටය යනු ස්වර පෙළක් පමණක් වන අතර රසය ජනනය කරමින් ගයන්නේ රාගයයි."),
        q("ථාටයක ස්වර පිහිටිය යුතු අනිවාර්ය අනුපිළිවෙළ කුමක්ද?", "ආරෝහණ ක්‍රමයෙන් පිළිවෙළට ස්වර 7ම තිබිය යුතුය", "වක්‍ර ගමනින් ස්වර 5ක් තිබිය යුතුය", "අවරෝහණ පමණක් තිබිය යුතුය", "එකම ස්වරය දෙවරක් නැතිව ස්වර 4ක් තිබීම", "ථාටය සැමවිටම සම්පූර්ණ විය යුතු අතර ස්වර ක්‍රමයෙන් ඉහළට සකස් විය යුතුය."),
        q("රාගයක 'අනුවාදී ස්වර' යනුවෙන් හඳුන්වනු ලබන්නේ කුමන ස්වරද?", "වාදී හා සංවාදී හැර රාගයේ යෙදෙන අනෙකුත් අනුගාමී ස්වර", "රාගයෙන් සම්පූර්ණයෙන් ඉවත් කළ ස්වර", "රාගය විකෘති කරන සතුරු ස්වර", "තාලයේ ඛාලි මාත්‍රාව", "රාග ගොඩනැගීමට සහාය වන වාදී-සංවාදී නොවන සියලු නිවැරදි ස්වර අනුවාදී වේ."),
        q("රාගයක 'විවාදී ස්වරය' යනුවෙන් අදහස් කරන්නේ කුමක්ද?", "රාගයේ සුන්දරත්වය හා රීතියට බාධා කරන සතුරු ස්වරය", "රාගයේ ප්‍රධාන රජ ස්වරය", "වැඩිපුරම නතර වන ස්වරය", "මූලික ආධාර ස්වරය", "විවාදී ස්වරය සතුරෙකුට උපමා කෙරෙන අතර අවසර නොමැතිව යෙදුවහොත් රාගය බිඳේ."),
        q("රාගයක 'වර්ජිත ස්වරය' (Varjitha Swara) යනු කුමක්ද?", "එම රාගයේ ආරෝහණයේ හෝ අවරෝහණයේ භාවිත නොකර අත්හරින ස්වරය", "සැමවිටම දිගු වේලාවක් අල්ලා සිටින ස්වරය", "මන්ද්‍ර සප්තකයේ මුල් ස්වරය", "තම්බුරාවේ ජෝඩි තන්තුව", "උදාහරණයක් ලෙස භූපාලි රාගයේ ම සහ නි වර්ජිත ස්වර වේ."),
        q("රාගයක ස්වර 'වක්‍ර' (Vakra) ගමනකින් යෙදෙනවා යනු කුමක්ද?", "ස්වර පිළිවෙළින් කෙළින් නොගොස් නැමී ආපසු හැරී ගමන් කිරීම", "තන්තු කැඩී යෑම", "තාලය වේගවත් වීම", "සප්තක තුනම එකවර ගැයීම", "බාගේශ්‍රී හෝ ගෞඩ් මල්හාර් වැනි රාගවල ඇතැම් ස්වර වක්‍රව යෙදේ."),
        q("රාග ගායනයේදී 'ග්‍රහ ස්වරය' යනු කුමක්ද?", "රාගයක් ගැයීම ආරම්භ කරන මූලික ස්වරය", "රාගය අවසන් කරන ස්වරය", "වර්ජිත කරන ලද ස්වරය", "විකෘති වන මධ්‍යමය", "පුරාණ ශාස්ත්‍රයේ රාග ආරම්භ කරන ස්වරය ග්‍රහ ලෙසත් නවතන ස්වරය න්‍යාස ලෙසත් හැඳින්වේ."),
        q("රාගයක 'න්‍යාස ස්වර' (Nyasa Swara) යනුවෙන් හඳුන්වනු ලබන්නේ මොනවාද?", "ආලාපයේදී හා ස්වර ඛණ්ඩවලදී නැවතී විරාම ගන්නා ස්වර", "ඉක්මනින් මඟහැර යන ස්වර", "රාගයෙන් ඉවත් කළ ස්වර", "තාලම්පට ගසන ස්ථාන", "ස, ග, ප හෝ වාදී ස්වර මත වැඩි වේලාවක් රැඳී විරාම ගැනීම න්‍යාස නම් වේ."),
        q("යම් රාගයක 'අල්පත්වය' (Alpatva) යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "එම රාගයේදී යම් ස්වරයක් ඉතා අඩුවෙන් හෝ ස්පර්ශ කර භාවිත කිරීම", "ස්වරයක් වැඩිපුරම යෙදීම", "රාගයේ මුළු ස්වර ගණන 22ක් වීම", "තාලයේ වේගය අඩු කිරීම", "වාදී-සංවාදී ස්වරවලට බහුත්වය ඇති අතර අඩුවෙන් ගන්නා ස්වරවලට අල්පත්වය ඇත."),
        q("රාගයක 'බහුත්වය' (Bahutva) පෙන්වන ප්‍රධානතම ස්වරය කුමක්ද?", "වාදී ස්වරය", "වර්ජිත ස්වරය", "විවාදී ස්වරය", "අනවශ්‍ය ස්වරය", "රාගය පුරා වැඩිපුරම යෙදෙන හා දීර්ඝව නවතින ස්වරය බහුත්වයෙන් යුක්ත වාදී ස්වරයයි."),
        q("රාගයක පූර්වාංගය හා උත්තරාංගය යන කොටස් දෙක වෙන් වන්නේ සප්තකයේ කවර ස්වර අනුවද?", "ස-රි-ග-ම (පූර්වාංගය) සහ ප-ධ-නි-සඃ (උත්තරාංගය)", "ස-රි (පූර්වාංගය) සහ ග-ම-ප (උත්තරාංගය)", "මන්ද්‍ර ස-රි සහ තාර ස-රි", "පමණක් ස සහ ප", "සප්තකයේ පහළ අර්ධය පූර්වාංගයද ඉහළ අර්ධය උත්තරාංගයද වේ."),
        q("'උත්තරාංග ප්‍රධාන රාග' ගායනා කිරීමට වඩාත් සුදුසු කාල සීමාව ලෙස සංගීත ශාස්ත්‍රයේ දක්වන්නේ කුමක්ද?", "මධ්‍යම රාත්‍රී 12 සිට දහවල් 12 දක්වා කාලය", "දහවල් 12 සිට රාත්‍රී 12 දක්වා කාලය", "සවස 6 සිට රාත්‍රී 9 දක්වා පමණක්", "අලුයම 4 සිට 5 දක්වා පමණක්", "පූර්වාංග රාග දවසේ පූර්ව භාගයේත් (12 PM–12 AM) උත්තරාංග රාග 12 AM–12 PM අතරත් ගැයේ."),
        q("'පූර්වාංග ප්‍රධාන රාග' සාමාන්‍යයෙන් ගායනා කරන කාල පරාසය කුමක්ද?", "දහවල් 12 සිට රාත්‍රී 12 දක්වා කාලය", "මධ්‍යම රාත්‍රී 12 සිට දහවල් 12 දක්වා කාලය", "උදෑසන 6 සිට 9 දක්වා පමණක්", "අලුයම 3 සිට 6 දක්වා පමණක්", "වාදී ස්වරය ස-රි-ග-ම අතර ඇති යමන්, භූපාලි, කාෆි වැනි රාග දහවල් 12 සිට රාත්‍රී 12 අතර ගැයේ."),
        q("'ආශ්‍රය රාගයක්' (Ashraya Raga) යනු කුමක්ද?", "ථාටයක නාමය හා සමාන නාමයක් ඇති එම ථාටයේ ප්‍රධාන රාගය", "වෙනත් ථාටයකින් සොරකම් කළ රාගය", "වර්ජිත ස්වර 4ක් ඇති රාගය", "තාලයක් නොමැති රාගය", "උදාහරණ ලෙස බිලාවල්, කල්‍යාණ් (යමන්), ඛමාජ්, කාෆි, භෛරව් යනු ඒ ඒ ථාටවල ආශ්‍රය රාග වේ."),
        q("දිවා රාත්‍රී දෙකෙහිම කෝමල රි සහ කෝමල ධ (රි̱, ධ̱) යෙදෙන රාග බහුලව ගැයෙන්නේ කවර වේලාවකද?", "උදෑසන සහ සවස සන්ධිප්‍රකාශ කාලවලදී", "දහවල් 12 සිට 3 දක්වා", "රාත්‍රී 9 සිට 12 දක්වා", "මධ්‍යම රාත්‍රී 12 සිට 3 දක්වා", "භෛරව්, පූර්වි, මාරවා වැනි සන්ධිප්‍රකාශ රාගවල රි̱ හා ධ̱ හෝ ම් ප්‍රමුඛ වේ."),
        q("'ප්‍රාතඃකාලීන සන්ධිප්‍රකාශ රාග' සහ 'සායංකාලීන සන්ධිප්‍රකාශ රාග' වෙන් කර හඳුනාගන්නා ප්‍රධාන ස්වරය කුමක්ද?", "මධ්‍යම ස්වරය", "ෂඩ්ජ ස්වරය", "පංචම ස්වරය", "ගාන්ධාර ස්වරය", "උදෑසන 4–7 රාගවල ශුද්ධ 'ම' ද සවස 4–7 රාගවල තීව්‍ර 'ම්' ද බහුලව යෙදේ."),
        q("කෝමල ගාන්ධාරය (ග̱) සහ කෝමල නිෂාදය (නි̱) යෙදෙන රාග බොහෝ විට ගැයෙන කාල සීමාව කුමක්ද?", "පෙරවරු 10–දහවල් 4 හෝ රාත්‍රී 10–අලුයම 4 අතර", "උදෑසන 4–7 අතර පමණක්", "සවස 4–7 අතර පමණක්", "ඕනෑම සන්ධි වේලාවක", "අසාවරී, කාෆි, බාගේශ්‍රී වැනි රාග සන්ධි කාලයෙන් පසුව ගැයේ."),
        q("ශුද්ධ රි, ශුද්ධ ග සහ ශුද්ධ ධ යෙදෙන රාග සඳහා වෙන්වූ ගායන වේලා කලාපය කුමක්ද?", "සන්ධි කාලයෙන් පසු උදෑසන (7–10) සහ රාත්‍රී (7–10) කාලය", "අලුයම 3–5 අතර", "මධ්‍යහ්න 1–3 අතර", "මධ්‍යම රාත්‍රී 1–3 අතර", "බිලාවල්, භූපාලි, යමන්, ඛමාජ් වැනි රාග පෙ.ව. 7–10 හෝ රාත්‍රී 7–10 අතර ගැයේ."),
        q("රාගයක 'තීව්‍ර මධ්‍යමය' (ම්) කාල සිද්ධාන්තයේදී හඳුන්වනු ලබන විශේෂ නාමය කුමක්ද?", "අධ්වදර්ශක ස්වරය", "වර්ජිත ස්වරය", "අචල ස්වරය", "මූල ෂඩ්ජ ස්වරය", "ශුද්ධ ම ද තීව්‍ර ම් ද යන්න මත රාගය උදේද සවසද යන්න හඳුනාගන්නා බැවින් මධ්‍යමය අධ්වදර්ශක වේ."),
        q("කිසියම් රාගයක 'ඕඩව - සම්පූර්ණ' ජාතිය පැවතීමෙන් පැහැදිලි වන කරුණ කුමක්ද?", "ආරෝහණයේ ස්වර 2ක් වර්ජිත වී අවරෝහණයේ සියලු ස්වර 7ම යෙදෙන බව", "ආරෝහණයේ ස්වර 7ක් හා අවරෝහණයේ 5ක් ඇති බව", "ස්වර 12ම යෙදෙන බව", "තාල දෙකක් ඇති බව", "උදාහරණයක් ලෙස භිම්පලාසි රාගය ආරෝහණය 5 හා අවරෝහණය 7 (ඕඩව-සම්පූර්ණ) වේ."),
        q("වර්තමානයේ භාවිත වන 'රාගාංග' වර්ගීකරණ ක්‍රමය හා ථාට 10 ක්‍රමය අතර ඇති සම්බන්ධය කුමක්ද?", "ප්‍රධාන ථාට හා රාගවල මූලික ස්වර ස්වරූපය අනුව ජන්‍ය රාග වර්ග කිරීම", "බටහිර සංගීතයට රාග පරිවර්තනය කිරීම", "රාග ගායනය සම්පූර්ණයෙන් නැවැත්වීම", "තබ්ලා ඝරානා බෙදා දැක්වීම", "කල්‍යාණ්, තෝඩි, භෛරව්, කානඩා ආදී මූලික අංග ඔස්සේ රාග පවුල් හඳුනාගැනේ."),
        q("උත්තර භාරතීය රාග වර්ගීකරණයේදී 'කාල සිද්ධාන්තයෙන් බැහැරව' ඕනෑම වේලාවක ගැයිය හැකි යැයි සැලකෙන සර්වකාලීන රාගයක් වන්නේ කුමක්ද?", "භෛරවී රාගය", "තෝඩි රාගය", "මාරවා රාගය", "පූර්වි රාගය", "භෛරවී රාගය ප්‍රසංග අවසානයේදී හා සර්වකාලීනව ගායනා කිරීමේ සම්ප්‍රදායක් පවතී."),
        q("සෘතු අනුව ගායනා කරන රාග අතර 'වර්ෂා සෘතුව' හා බැඳුණු ප්‍රසිද්ධ රාගය කුමක්ද?", "මල්හාර් රාගය", "භෛරව් රාගය", "බිලාවල් රාගය", "භූපාලි රාගය", "වැසි සමයේ මේඝ හා මල්හාර් රාගයන්ද වසන්ත සමයේ බසන්ත් හා බහාර් රාගයන්ද ගැයේ."),
        q("වසන්ත සෘතුවේදී (Spring) ගායනා කිරීම සඳහා වෙන්වූ උත්තර භාරතීය රාග යුගලය කුමක්ද?", "බසන්ත් සහ බහාර්", "දීපක් සහ මල්හාර්", "භූපාලි සහ දේශ්කාර්", "භෛරව් සහ තෝඩි", "හෝලි වසන්ත උත්සව සමයේදී බසන්ත් හා බහාර් රාග විශේෂයෙන් ගායනා කෙරේ."),
        q("ශුද්ධ, ඡායාලග සහ සංකීර්ණ යනු කවර භාරතීය සංගීත වර්ගීකරණයකට අයත් ප්‍රභේද තුනක්ද?", "රාග වර්ගීකරණය (මිශ්‍ර වීමේ ස්වභාවය අනුව)", "තාල වර්ගීකරණය", "වාද්‍ය භාණ්ඩ වර්ගීකරණය", "සප්තක වර්ගීකරණය", "තනි රාග ලක්ෂණ (ශුද්ධ), වෙනත් රාග ඡායාවක් ඇති (ඡායාලග) හා රාග කිහිපයක් එක්වූ (සංකීර්ණ) වේ.")
    )
}
